// Error tracking via self-hosted GlitchTip (Sentry-compatible SDK).
// Must be imported before anything else so auto-instrumentation can hook in.
import * as Sentry from '@sentry/node';

if (process.env.GLITCHTIP_DSN) {
  Sentry.init({
    dsn: process.env.GLITCHTIP_DSN,
    environment: process.env.NODE_ENV || 'development',
    // GlitchTip handles errors only; keep performance tracing off.
    tracesSampleRate: 0,
  });
}

export { Sentry };

import { Sentry } from './instrument.js';
import express from 'express';
import { listsForHousehold } from './lists.js';

const app = express();
app.use(express.json());

app.get('/households/:id/lists', async (req, res) => {
  res.json(await listsForHousehold(req.params.id));
});

// After all routes: report errors to GlitchTip, then fall through to Express's default handler.
Sentry.setupExpressErrorHandler(app);

process.on('unhandledRejection', (err) => {
  Sentry.captureException(err);
  console.error(err);
});

app.listen(process.env.PORT || 3000);
